package dev.aether.api.security;
import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.http.HttpMethod;import org.springframework.security.authentication.AuthenticationManager;import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import org.springframework.web.cors.CorsConfiguration;import org.springframework.web.cors.CorsConfigurationSource;import org.springframework.web.cors.UrlBasedCorsConfigurationSource;import java.util.Arrays;import java.util.List;
@Configuration @EnableWebSecurity @EnableMethodSecurity public class SecurityConfig { private final JwtAuthenticationFilter jwtFilter;private final String allowedOrigins;public SecurityConfig(JwtAuthenticationFilter jwtFilter,@Value("${security.cors.allowed-origins}")String allowedOrigins){this.jwtFilter=jwtFilter;this.allowedOrigins=allowedOrigins;}@Bean SecurityFilterChain filterChain(HttpSecurity http)throws Exception{return http.csrf(csrf->csrf.disable()).cors(cors->cors.configurationSource(corsConfigurationSource())).sessionManagement(session->session.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(auth->auth.requestMatchers(HttpMethod.OPTIONS,"/**").permitAll().requestMatchers("/api/v1/auth/**","/api/v1/hero","/api/v1/services","/api/v1/technologies","/api/v1/capabilities","/api/v1/process","/api/v1/case-studies","/api/v1/industries","/api/v1/testimonials","/api/v1/team","/api/v1/site-settings","/api/v1/contact","/actuator/health/**").permitAll().anyRequest().authenticated()).addFilterBefore(jwtFilter,UsernamePasswordAuthenticationFilter.class).build();}@Bean CorsConfigurationSource corsConfigurationSource(){CorsConfiguration config=new CorsConfiguration();config.setAllowedOrigins(Arrays.stream(allowedOrigins.split(",")).map(String::trim).toList());config.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));config.setAllowedHeaders(List.of("Authorization","Content-Type","Accept"));config.setExposedHeaders(List.of("Location"));config.setAllowCredentials(true);UrlBasedCorsConfigurationSource source=new UrlBasedCorsConfigurationSource();source.registerCorsConfiguration("/**",config);return source;}@Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);}@Bean AuthenticationManager authenticationManager(AuthenticationConfiguration configuration)throws Exception{return configuration.getAuthenticationManager();} }
